
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ft97_a_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ft97_a", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.290384387466768e+00, -4.208635328806252e+00, -4.094212586630528e+00, -3.935979708166194e+00, -3.720949856128660e+00, -3.436029644880040e+00, -3.072106367148090e+00, -2.631511336286269e+00, -2.138059459923522e+00, -1.637084220142431e+00, -1.130611851664968e+00, -7.101342482772497e-01, -6.007747650040901e-01, -4.997022068245476e-01, -3.729637701170901e-01, -2.596171506871199e-01, -1.761292341861007e-01, -1.076706253595347e-01, -6.512038918556715e-02, -4.349157318287475e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


